<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { api } from '../../api'
const items=ref<any[]>([]),total=ref(0),loading=ref(false),counts=reactive<any>({}),filter=reactive({usage:'pending',supplier:'',search:'',include_deleted:false,page:1})
async function load(){loading.value=true;try{const q=new URLSearchParams({...filter,page:String(filter.page),page_size:'50'} as any);const data=await api.get<any>(`/pod/supplier-gallery?${q}`);items.value=data.items||[];total.value=data.total||0;Object.assign(counts,data.counts||{})}finally{loading.value=false}}
async function clearItem(row:any){await ElMessageBox.confirm(`确认清理供应商素材 ${row.code}？本地图库和产品文件会保留。`,'清理远程素材',{type:'warning'});if(row.supplier==='s2b'){await api.post(`/pod/supplier-gallery/${row.supplier}/${encodeURIComponent(row.code)}/mark-deleted`,{});ElMessage.success('已标记为在 S2B 后台清理')}else{await api.delete(`/pod/supplier-gallery/${row.supplier}/${encodeURIComponent(row.code)}`);ElMessage.success('已加入清理任务，可在任务中心查看进度')}load()}
async function syncGallery(){const result=await api.post<any>(`/pod/supplier-gallery/sync?supplier=${filter.supplier}`,{});ElMessage.success('图库同步任务已建立，可离开页面');load()}
async function cleanupPending(){await ElMessageBox.confirm(`只会删除未出单且未受保护的供应商素材；已出单图库绝不会删除。确认继续？`,'一键清理未出单图库',{type:'warning'});const result=await api.post<any>(`/pod/supplier-gallery/cleanup-pending?supplier=${filter.supplier}`,{});ElMessage.success(`已建立 ${result.queued} 个清理任务${result.unsupported?`；${result.unsupported} 个S2B素材需在供应商后台清理`:''}`);load()}
onMounted(load)
</script>
<template><div class="page-stack"><section class="metric-grid"><div class="metric-card"><strong>{{counts.total||0}}</strong><span>全部远程素材</span></div><div class="metric-card"><strong>{{counts.pending||0}}</strong><span>未出单</span></div><div class="metric-card"><strong>{{counts.ordered||0}}</strong><span>已出单</span></div><div class="metric-card"><strong>{{counts.cleanup_candidates||0}}</strong><span>可清理</span></div></section><section class="panel"><div class="panel-head"><div><h2>供应商图库</h2><p>订单成功后素材自动标记为已出单并永久保护；重复采购同一SKU时复用已有素材</p></div><div><el-button @click="syncGallery">同步供应商图库</el-button><el-button type="danger" plain :disabled="!counts.cleanup_candidates" @click="cleanupPending">一键清理未出单 ({{counts.cleanup_candidates||0}})</el-button></div></div><div class="panel-body"><div class="toolbar"><el-input v-model="filter.search" clearable placeholder="SKU、产品、素材编号或订单" @keyup.enter="filter.page=1;load()"/><el-select v-model="filter.usage" clearable placeholder="全部用途"><el-option label="未出单" value="pending"/><el-option label="已出单" value="ordered"/></el-select><el-select v-model="filter.supplier" clearable placeholder="全部供应商"><el-option label="HICUSTOM" value="hicustom"/><el-option label="S2B" value="s2b"/></el-select><el-checkbox v-model="filter.include_deleted">显示已清理</el-checkbox><el-button @click="filter.page=1;load()">查询</el-button></div><el-table v-loading="loading" :data="items"><el-table-column label="预览" width="90"><template #default="s"><el-image v-if="s.row.thumbnail_url" :src="s.row.thumbnail_url" fit="cover" style="width:56px;height:56px;border-radius:6px"/></template></el-table-column><el-table-column label="素材" min-width="220"><template #default="s"><b>{{s.row.filename||s.row.code}}</b><small class="table-sub mono">{{s.row.code}}</small></template></el-table-column><el-table-column prop="supplier_name" label="供应商" width="120"/><el-table-column label="关联产品" min-width="210"><template #default="s">{{s.row.product_name||'-'}}<small class="table-sub mono">{{s.row.sku}}</small></template></el-table-column><el-table-column label="用途" width="110"><template #default="s"><el-tag :type="s.row.usage==='ordered'?'success':'warning'">{{s.row.usage_name}}</el-tag></template></el-table-column><el-table-column label="订单" min-width="180"><template #default="s">{{(s.row.order_ids||[]).join('、')||'-'}}</template></el-table-column><el-table-column label="保护" width="100"><template #default="s"><el-tag v-if="s.row.protected" type="danger">禁止清理</el-tag><span v-else>-</span></template></el-table-column><el-table-column label="操作" width="130"><template #default="s"><el-button v-if="s.row.cleanup_candidate&&!s.row.remote_deleted" link type="danger" @click="clearItem(s.row)">{{s.row.supplier==='s2b'?'标记已清理':'清理远程'}}</el-button><el-tag v-else-if="s.row.remote_deleted" type="info">已清理</el-tag></template></el-table-column></el-table><el-pagination v-model:current-page="filter.page" :page-size="50" :total="total" layout="prev, pager, next, total" @current-change="load"/></div></section></div></template>
